 *
 ****************************************************************************/

/****************************************************************************
 * ESP32-S3 Camera (LCD_CAM CAM interface) Driver
 *
 * This driver uses the LCD_CAM peripheral's camera section to capture
 * 8-bit parallel data from an OV2640 camera sensor. It implements the
 * imgdata_ops_s interface for integration with the V4L2 capture framework.
 *
 * Data flow:
 *   OV2640 --[DVP 8-bit]--> LCD_CAM CAM --[DMA]--> framebuffer
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <debug.h>

#include <nuttx/arch.h>
#include <nuttx/kmalloc.h>
#include <nuttx/video/imgdata.h>
#include <nuttx/spinlock.h>

#include "esp32s3_cam.h"
#include "esp32s3_gpio.h"
#include "esp32s3_dma.h"
#include "esp32s3_irq.h"
#include "esp32s3_clockconfig.h"

#include "hardware/esp32s3_gpio_sigmap.h"
#include "hardware/esp32s3_lcd_cam.h"
#include "hardware/esp32s3_system.h"

#include "periph_ctrl.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* Camera data pins (D0-D7) - board-specific, defined in board header */

#ifndef ESP32S3_CAM_PIN_D0
#  define ESP32S3_CAM_PIN_D0   11
#endif
#ifndef ESP32S3_CAM_PIN_D1
#  define ESP32S3_CAM_PIN_D1    9
#endif
#ifndef ESP32S3_CAM_PIN_D2
#  define ESP32S3_CAM_PIN_D2    8
#endif
#ifndef ESP32S3_CAM_PIN_D3
#  define ESP32S3_CAM_PIN_D3   10
#endif
#ifndef ESP32S3_CAM_PIN_D4
#  define ESP32S3_CAM_PIN_D4   12
#endif
#ifndef ESP32S3_CAM_PIN_D5
#  define ESP32S3_CAM_PIN_D5   18
#endif
#ifndef ESP32S3_CAM_PIN_D6
#  define ESP32S3_CAM_PIN_D6   17
#endif
#ifndef ESP32S3_CAM_PIN_D7
#  define ESP32S3_CAM_PIN_D7   16
#endif
#ifndef ESP32S3_CAM_PIN_PCLK
#  define ESP32S3_CAM_PIN_PCLK 13
#endif
#ifndef ESP32S3_CAM_PIN_VSYNC
#  define ESP32S3_CAM_PIN_VSYNC 6
#endif
#ifndef ESP32S3_CAM_PIN_HREF
#  define ESP32S3_CAM_PIN_HREF  7
#endif
#ifndef ESP32S3_CAM_PIN_XCLK
#  define ESP32S3_CAM_PIN_XCLK 15
#endif

/* XCLK frequency for OV2640 */

#define ESP32S3_CAM_XCLK_FREQ   20000000  /* 20 MHz */

/* CAM DMA */

#define ESP32S3_CAM_DMA_CHAN    0
#define ESP32S3_CAM_DMA_DESC_NUM 1

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct esp32s3_cam_s
{
  struct imgdata_s          data;     /* Image data interface (must be first) */
  volatile bool             capturing;
  volatile bool             frame_done;
  uint8_t                  *buf;
  uint32_t                  buf_size;
  uint16_t                  width;
  uint16_t                  height;
  imgdata_capture_t         callback;
  void                     *cb_arg;
  int32_t                   dma_channel;
  struct esp32s3_dmadesc_s  dma_desc[ESP32S3_CAM_DMA_DESC_NUM];
  spinlock_t                lock;
};

/****************************************************************************
 * Private Function Prototypes
 ****************************************************************************/

/* imgdata_ops_s interface */

static int esp32s3_cam_init(FAR struct imgdata_s *data);
static int esp32s3_cam_uninit(FAR struct imgdata_s *data);
static int esp32s3_cam_set_buf(FAR struct imgdata_s *data,
                                uint8_t nr_datafmts,
                                FAR imgdata_format_t *datafmts,
                                uint8_t *addr, uint32_t size);
static int esp32s3_cam_validate(FAR struct imgdata_s *data,
                                 uint8_t nr_datafmts,
                                 FAR imgdata_format_t *datafmts,
                                 FAR imgdata_interval_t *interval);
static int esp32s3_cam_start_capture(FAR struct imgdata_s *data,
                                      uint8_t nr_datafmts,
                                      FAR imgdata_format_t *datafmts,
                                      FAR imgdata_interval_t *interval,
                                      FAR imgdata_capture_t callback,
                                      FAR void *arg);
static int esp32s3_cam_stop_capture(FAR struct imgdata_s *data);

/* Internal functions */

static void esp32s3_cam_configure_pins(void);
static void esp32s3_cam_start_xclk(void);
static void esp32s3_cam_configure_dma(FAR struct esp32s3_cam_s *priv);
static int  esp32s3_cam_interrupt(int irq, void *context, void *arg);

/****************************************************************************
 * Private Data
 ****************************************************************************/

static const struct imgdata_ops_s g_esp32s3_cam_ops =
{
  .init                   = esp32s3_cam_init,
  .uninit                 = esp32s3_cam_uninit,
  .set_buf                = esp32s3_cam_set_buf,
  .validate_frame_setting = esp32s3_cam_validate,
  .start_capture          = esp32s3_cam_start_capture,
  .stop_capture           = esp32s3_cam_stop_capture,
  .alloc                  = NULL,
  .free                   = NULL,
};

static struct esp32s3_cam_s g_esp32s3_cam;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: esp32s3_cam_configure_pins
 *
 * Description:
 *   Configure GPIO pins for camera DVP interface (8-bit parallel data +
 *   PCLK, VSYNC, HREF) and XCLK output.
 *
 ****************************************************************************/

static void esp32s3_cam_configure_pins(void)
{
  /* Configure XCLK output pin */

  esp32s3_configgpio(ESP32S3_CAM_PIN_XCLK, OUTPUT);
  esp32s3_gpio_matrix_out(ESP32S3_CAM_PIN_XCLK,
                           CLK_OUT1_IDX, 0, 0);

  /* Configure data pins D0-D7 as input */

  esp32s3_configgpio(ESP32S3_CAM_PIN_D0, INPUT);
  esp32s3_configgpio(ESP32S3_CAM_PIN_D1, INPUT);
  esp32s3_configgpio(ESP32S3_CAM_PIN_D2, INPUT);
  esp32s3_configgpio(ESP32S3_CAM_PIN_D3, INPUT);
  esp32s3_configgpio(ESP32S3_CAM_PIN_D4, INPUT);
  esp32s3_configgpio(ESP32S3_CAM_PIN_D5, INPUT);
  esp32s3_configgpio(ESP32S3_CAM_PIN_D6, INPUT);
  esp32s3_configgpio(ESP32S3_CAM_PIN_D7, INPUT);

  /* Connect data pins to LCD_CAM CAM data signals */

  esp32s3_gpio_matrix_out(ESP32S3_CAM_PIN_D0,
                           CAM_DATA_IN0_IDX, 0, 0);
  esp32s3_gpio_matrix_out(ESP32S3_CAM_PIN_D1,
                           CAM_DATA_IN1_IDX, 0, 0);
  esp32s3_gpio_matrix_out(ESP32S3_CAM_PIN_D2,
                           CAM_DATA_IN2_IDX, 0, 0);
  esp32s3_gpio_matrix_out(ESP32S3_CAM_PIN_D3,
                           CAM_DATA_IN3_IDX, 0, 0);
  esp32s3_gpio_matrix_out(ESP32S3_CAM_PIN_D4,
                           CAM_DATA_IN4_IDX, 0, 0);
  esp32s3_gpio_matrix_out(ESP32S3_CAM_PIN_D5,
                           CAM_DATA_IN5_IDX, 0, 0);
  esp32s3_gpio_matrix_out(ESP32S3_CAM_PIN_D6,
                           CAM_DATA_IN6_IDX, 0, 0);
  esp32s3_gpio_matrix_out(ESP32S3_CAM_PIN_D7,
                           CAM_DATA_IN7_IDX, 0, 0);

  /* Configure PCLK, VSYNC, HREF as input */

  esp32s3_configgpio(ESP32S3_CAM_PIN_PCLK, INPUT);
  esp32s3_configgpio(ESP32S3_CAM_PIN_VSYNC, INPUT);
  esp32s3_configgpio(ESP32S3_CAM_PIN_HREF, INPUT);

  /* Connect to LCD_CAM CAM control signals */

  esp32s3_gpio_matrix_out(ESP32S3_CAM_PIN_PCLK,
                           CAM_PCLK_IDX, 0, 0);
  esp32s3_gpio_matrix_out(ESP32S3_CAM_PIN_VSYNC,
                           CAM_V_SYNC_IDX, 0, 0);
  esp32s3_gpio_matrix_out(ESP32S3_CAM_PIN_HREF,
                           CAM_H_ENABLE_IDX, 0, 0);
}

/****************************************************************************
 * Name: esp32s3_cam_start_xclk
 *
 * Description:
 *   Generate XCLK for the camera sensor using CLK_OUT1.
 *
 ****************************************************************************/

static void esp32s3_cam_start_xclk(void)
{
  /* Use PLL_F160M (160MHz) as clock source, divide to get ~20MHz */

  uint32_t regval;

  /* Enable clock output via CLK_OUT1 */

  regval = getreg32(ESP32S3_SYSTEM_PERIP_CLK_EN0_REG);
  regval |= ESP32S3_SYSTEM_CLK_EN_M;
  putreg32(regval, ESP32S3_SYSTEM_PERIP_CLK_EN0_REG);

  /* Configure CLK_OUT1: source = PLL_F160M, divider = 8 -> 20MHz */

  regval = 0;
  regval |= (2 << ESP32S3_SYSTEM_CLK_OUT1_SEL_S);  /* PLL_F160M */
  regval |= (7 << ESP32S3_SYSTEM_CLK_160M_EN_S);    /* div = 8 */
  putreg32(regval, ESP32S3_SYSTEM_SYSCLK_CONF_REG);
}

/****************************************************************************
 * Name: esp32s3_cam_configure_dma
 *
 * Description:
 *   Configure DMA for camera data transfer.
 *
 ****************************************************************************/

static void esp32s3_cam_configure_dma(FAR struct esp32s3_cam_s *priv)
{
  priv->dma_channel = esp32s3_dma_request(
                        ESP32S3_DMA_PERIPH_LCDCAM,
                        ESP32S3_CAM_DMA_CHAN,
                        ESP32S3_DMA_CHANNEL_FLAG_NONE);

  if (priv->dma_channel < 0)
    {
      camerr("ERROR: Failed to allocate DMA channel\n");
      return;
    }

  /* Configure DMA descriptor */

  esp32s3_dma_config(priv->dma_channel,
                     ESP32S3_CAM_DMA_DESC_NUM,
                     priv->dma_desc,
                     0);  /* No peripheral trigger needed for CAM */
}

/****************************************************************************
 * Name: esp32s3_cam_interrupt
 *
 * Description:
 *   DMA completion interrupt handler. Called when a frame is captured.
 *
 ****************************************************************************/

static int esp32s3_cam_interrupt(int irq, void *context, void *arg)
{
  FAR struct esp32s3_cam_s *priv = (FAR struct esp32s3_cam_s *)arg;
  irqstate_t flags;

  flags = spin_lock_irqsave(&priv->lock);

  priv->frame_done = true;

  if (priv->callback)
    {
      struct timeval tv;
      gettimeofday(&tv, NULL);
      priv->callback(0, priv->buf_size, &tv, priv->cb_arg);
    }

  spin_unlock_irqrestore(&priv->lock, flags);
  return OK;
}

/****************************************************************************
 * Name: esp32s3_cam_init
 ****************************************************************************/

static int esp32s3_cam_init(FAR struct imgdata_s *data)
{
  FAR struct esp32s3_cam_s *priv = (FAR struct esp32s3_cam_s *)data;

  caminfo("Initializing ESP32-S3 camera interface\n");

  /* Enable LCD_CAM peripheral clock */

  periph_ctrl_enable(PERIPH_LCDCAM_MODULE);
  periph_ctrl_reset(PERIPH_LCDCAM_MODULE);

  /* Configure GPIO pins for camera */

  esp32s3_cam_configure_pins();

  /* Start XCLK for camera sensor */

  esp32s3_cam_start_xclk();

  /* Configure DMA */

  esp32s3_cam_configure_dma(priv);

  /* Set CAM interface registers for 8-bit input, VSYNC active high */

  uint32_t regval;

  /* CAM_CTRL: Enable camera, 8-bit data width, VSYNC active high */

  regval = LCD_CAM_CAM_UPDATE_REG;
  putreg32(regval, LCD_CAM_CAM_CTRL_REG);

  regval = LCD_CAM_CAM_START;
  putreg32(regval, LCD_CAM_CAM_CTRL1_REG);

  priv->capturing = false;
  priv->frame_done = false;

  caminfo("Camera interface initialized\n");
  return OK;
}

/****************************************************************************
 * Name: esp32s3_cam_uninit
 ****************************************************************************/

static int esp32s3_cam_uninit(FAR struct imgdata_s *data)
{
  FAR struct esp32s3_cam_s *priv = (FAR struct esp32s3_cam_s *)data;

  caminfo("Uninitializing camera interface\n");

  /* Stop any ongoing capture */

  if (priv->capturing)
    {
      esp32s3_cam_stop_capture(data);
    }

  /* Free DMA channel */

  if (priv->dma_channel >= 0)
    {
      esp32s3_dma_free(priv->dma_channel);
      priv->dma_channel = -1;
    }

  /* Disable LCD_CAM peripheral */

  periph_ctrl_disable(PERIPH_LCDCAM_MODULE);

  return OK;
}

/****************************************************************************
 * Name: esp32s3_cam_set_buf
 ****************************************************************************/

static int esp32s3_cam_set_buf(FAR struct imgdata_s *data,
                                uint8_t nr_datafmts,
                                FAR imgdata_format_t *datafmts,
                                uint8_t *addr, uint32_t size)
{
  FAR struct esp32s3_cam_s *priv = (FAR struct esp32s3_cam_s *)data;

  if (nr_datafmts == 0 || datafmts == NULL)
    {
      return -EINVAL;
    }

  priv->buf      = addr;
  priv->buf_size = size;
  priv->width    = datafmts[0].width;
  priv->height   = datafmts[0].height;

  caminfo("Buffer set: %dx%d, size=%lu\n",
          priv->width, priv->height, (unsigned long)size);

  return OK;
}

/****************************************************************************
 * Name: esp32s3_cam_validate
 ****************************************************************************/

static int esp32s3_cam_validate(FAR struct imgdata_s *data,
                                 uint8_t nr_datafmts,
                                 FAR imgdata_format_t *datafmts,
                                 FAR imgdata_interval_t *interval)
{
  if (nr_datafmts == 0 || datafmts == NULL)
    {
      return -EINVAL;
    }

  /* Support RGB565 format */

  if (datafmts[0].pixelformat != IMGDATA_PIX_FMT_RGB565)
    {
      camerr("Unsupported pixel format: %lu\n",
             (unsigned long)datafmts[0].pixelformat);
      return -EINVAL;
    }

  caminfo("Validation OK: %dx%d\n",
          datafmts[0].width, datafmts[0].height);
  return OK;
}

/****************************************************************************
 * Name: esp32s3_cam_start_capture
 ****************************************************************************/

static int esp32s3_cam_start_capture(FAR struct imgdata_s *data,
                                      uint8_t nr_datafmts,
                                      FAR imgdata_format_t *datafmts,
                                      FAR imgdata_interval_t *interval,
                                      FAR imgdata_capture_t callback,
                                      FAR void *arg)
{
  FAR struct esp32s3_cam_s *priv = (FAR struct esp32s3_cam_s *)data;
  irqstate_t flags;

  if (priv->buf == NULL)
    {
      camerr("ERROR: No buffer set\n");
      return -ENOMEM;
    }

  caminfo("Starting capture: %dx%d\n", priv->width, priv->height);

  flags = spin_lock_irqsave(&priv->lock);

  priv->callback  = callback;
  priv->cb_arg    = arg;
  priv->frame_done = false;
  priv->capturing  = true;

  /* Configure DMA to receive data into buffer */

  esp32s3_dma_load(priv->dma_channel, priv->dma_desc,
                   priv->buf, priv->buf_size);

  /* Enable DMA interrupt */

  esp32s3_dma_enable_interrupt(priv->dma_channel);

  /* Start DMA */

  esp32s3_dma_enable(priv->dma_channel);

  /* Start camera capture */

  uint32_t regval;
  regval = getreg32(LCD_CAM_CAM_CTRL1_REG);
  regval |= LCD_CAM_CAM_START;
  putreg32(regval, LCD_CAM_CAM_CTRL1_REG);

  spin_unlock_irqrestore(&priv->lock, flags);

  caminfo("Capture started\n");
  return OK;
}

/****************************************************************************
 * Name: esp32s3_cam_stop_capture
 ****************************************************************************/

static int esp32s3_cam_stop_capture(FAR struct imgdata_s *data)
{
  FAR struct esp32s3_cam_s *priv = (FAR struct esp32s3_cam_s *)data;
  irqstate_t flags;

  flags = spin_lock_irqsave(&priv->lock);

  if (!priv->capturing)
    {
      spin_unlock_irqrestore(&priv->lock, flags);
      return OK;
    }

  /* Stop camera capture */

  uint32_t regval;
  regval = getreg32(LCD_CAM_CAM_CTRL1_REG);
  regval &= ~LCD_CAM_CAM_START;
  putreg32(regval, LCD_CAM_CAM_CTRL1_REG);

  /* Stop DMA */

  esp32s3_dma_disable(priv->dma_channel);
  esp32s3_dma_disable_interrupt(priv->dma_channel);

  priv->capturing = false;
  priv->callback  = NULL;
  priv->cb_arg    = NULL;

  spin_unlock_irqrestore(&priv->lock, flags);

  caminfo("Capture stopped\n");
  return OK;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: esp32s3_cam_initialize
 *
 * Description:
 *   Initialize the ESP32-S3 camera data interface and register it.
 *
 ****************************************************************************/

int esp32s3_cam_initialize(void)
{
  FAR struct esp32s3_cam_s *priv = &g_esp32s3_cam;
  int ret;

  caminfo("Registering ESP32-S3 camera data interface\n");

  memset(priv, 0, sizeof(struct esp32s3_cam_s));
  priv->data.ops = &g_esp32s3_cam_ops;
  priv->dma_channel = -1;

  /* Register image data interface */

  imgdata_register(&priv->data);

  caminfo("Camera data interface registered\n");
  return OK;
}

