 *
 ****************************************************************************/

int board_camera_initialize(void)
{
  FAR struct i2c_master_s *i2c;
  int ret;

  caminfo("Initializing OV2640 camera\n");

  /* Initialize I2C bus for SCCB (OV2640 configuration) */

  i2c = esp32s3_i2cbus_initialize(0);  /* I2C port 0 */
  if (i2c == NULL)
    {
      camerr("ERROR: Failed to initialize I2C bus\n");
      return -ENODEV;
    }

  /* Initialize OV2640 sensor (registers image sensor with V4L2 framework) */

  ret = ov2640_initialize(i2c);
  if (ret < 0)
    {
      camerr("ERROR: ov2640_initialize failed: %d\n", ret);
      return ret;
    }

  /* Initialize ESP32-S3 camera data interface (registers imgdata) */

  ret = esp32s3_cam_initialize();
  if (ret < 0)
    {
      camerr("ERROR: esp32s3_cam_initialize failed: %d\n", ret);
      return ret;
    }

  /* Register V4L2 capture device at /dev/video */

  ret = capture_register("/dev/video", NULL, NULL, 0);
  if (ret < 0)
    {
      camerr("ERROR: capture_register failed: %d\n", ret);
      return ret;
    }

  caminfo("Camera initialized successfully\n");
  return OK;
}

