/****************************************************************************
 * Contest 2026 team 026 - OV2640 Camera Real-time Display
 *
 * Captures frames from OV2640 camera via V4L2 interface and displays
 * them on the ST7789 LCD in real-time.
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/time.h>

#include <nuttx/video/video.h>
#include <nuttx/video/v4l2_cap.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define CAMERA_DEV_PATH   "/dev/video"
#define FRAME_WIDTH       320
#define FRAME_HEIGHT      240
#define FRAME_SIZE        (FRAME_WIDTH * FRAME_HEIGHT * 2)  /* RGB565 */
#define LCD_WIDTH         240
#define LCD_HEIGHT        240
#define BUF_COUNT         3

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct frame_buffer_s
{
  uint8_t *start;
  uint32_t length;
};

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: camera_prepare
 *
 * Description:
 *   Set up camera for RGB565 QVGA capture.
 ****************************************************************************/

static int camera_prepare(int fd)
{
  struct v4l2_format fmt;
  struct v4l2_requestbuffers req;
  struct v4l2_buffer buf;
  int ret;
  int i;

  /* Set format: QVGA RGB565 */

  memset(&fmt, 0, sizeof(fmt));
  fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  fmt.fmt.pix.width = FRAME_WIDTH;
  fmt.fmt.pix.height = FRAME_HEIGHT;
  fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_RGB565;

  ret = ioctl(fd, VIDIOC_S_FMT, (unsigned long)&fmt);
  if (ret < 0)
    {
      printf("ERROR: VIDIOC_S_FMT failed: %d\n", errno);
      return ret;
    }

  /* Request buffers */

  memset(&req, 0, sizeof(req));
  req.count = BUF_COUNT;
  req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  req.memory = V4L2_MEMORY_MMAP;

  ret = ioctl(fd, VIDIOC_REQBUFS, (unsigned long)&req);
  if (ret < 0)
    {
      printf("ERROR: VIDIOC_REQBUFS failed: %d\n", errno);
      return ret;
    }

  /* Queue all buffers */

  for (i = 0; i < BUF_COUNT; i++)
    {
      memset(&buf, 0, sizeof(buf));
      buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
      buf.memory = V4L2_MEMORY_MMAP;
      buf.index = i;

      ret = ioctl(fd, VIDIOC_QBUF, (unsigned long)&buf);
      if (ret < 0)
        {
          printf("ERROR: VIDIOC_QBUF failed: %d\n", errno);
          return ret;
        }
    }

  return OK;
}

/****************************************************************************
 * Name: display_frame_lcd
 *
 * Description:
 *   Write RGB565 frame data directly to LCD device, cropped to 240x240.
 ****************************************************************************/

static int display_frame_lcd(const uint8_t *frame)
{
  static int lcd_fd = -1;
  struct lcddev_area_s area;
  int ret;
  int y;

  if (lcd_fd < 0)
    {
      lcd_fd = open("/dev/lcd0", O_WRONLY);
      if (lcd_fd < 0)
        {
          printf("ERROR: Failed to open /dev/lcd0: %d\n", errno);
          return -errno;
        }
    }

  /* Crop 320x240 -> 240x240: skip 40 pixels on each side (center crop) */

  for (y = 0; y < LCD_HEIGHT; y++)
    {
      const uint8_t *src = frame + (y * FRAME_WIDTH + 40) * 2;

      memset(&area, 0, sizeof(area));
      area.row_start = y;
      area.row_end = y;
      area.col_start = 0;
      area.col_end = LCD_WIDTH - 1;
      area.data = (uint8_t *)src;

      ret = ioctl(lcd_fd, LCDDEVIO_PUTAREA, (unsigned long)&area);
      if (ret < 0)
        {
          printf("ERROR: LCDDEVIO_PUTAREA failed at row %d: %d\n",
                 y, errno);
          return ret;
        }
    }

  return OK;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, char *argv[])
{
  int fd;
  int ret;
  struct v4l2_buffer buf;
  enum v4l2_buf_type type;
  uint8_t *frame_data;
  struct timeval start_tv;
  struct timeval now_tv;
  int frame_count = 0;

  printf("OV2640 Camera -> LCD Real-time Display\n");

  /* Open camera device */

  fd = open(CAMERA_DEV_PATH, O_RDONLY);
  if (fd < 0)
    {
      printf("ERROR: Failed to open %s: %d\n", CAMERA_DEV_PATH, errno);
      return -errno;
    }

  /* Prepare camera */

  ret = camera_prepare(fd);
  if (ret < 0)
    {
      printf("ERROR: camera_prepare failed: %d\n", ret);
      close(fd);
      return ret;
    }

  /* Start streaming */

  type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  ret = ioctl(fd, VIDIOC_STREAMON, (unsigned long)&type);
  if (ret < 0)
    {
      printf("ERROR: VIDIOC_STREAMON failed: %d\n", errno);
      close(fd);
      return ret;
    }

  printf("Camera streaming started. Displaying on LCD...\n");
  gettimeofday(&start_tv, NULL);

  /* Main capture loop */

  while (1)
    {
      /* Dequeue a frame */

      memset(&buf, 0, sizeof(buf));
      buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
      buf.memory = V4L2_MEMORY_MMAP;

      ret = ioctl(fd, VIDIOC_DQBUF, (unsigned long)&buf);
      if (ret < 0)
        {
          printf("ERROR: VIDIOC_DQBUF failed: %d\n", errno);
          break;
        }

      /* Get frame data pointer */

      frame_data = (uint8_t *)buf.m.offset;

      /* Display frame on LCD */

      ret = display_frame_lcd(frame_data);
      if (ret < 0)
        {
          printf("ERROR: display_frame_lcd failed: %d\n", ret);
        }

      /* Requeue buffer */

      ret = ioctl(fd, VIDIOC_QBUF, (unsigned long)&buf);
      if (ret < 0)
        {
          printf("ERROR: VIDIOC_QBUF failed: %d\n", errno);
          break;
        }

      /* Print FPS every second */

      frame_count++;
      gettimeofday(&now_tv, NULL);
      long elapsed_ms = (now_tv.tv_sec - start_tv.tv_sec) * 1000 +
                        (now_tv.tv_usec - start_tv.tv_usec) / 1000;

      if (elapsed_ms >= 1000)
        {
          printf("FPS: %ld\n", frame_count * 1000 / elapsed_ms);
          frame_count = 0;
          start_tv = now_tv;
        }
    }

  /* Cleanup */

  ioctl(fd, VIDIOC_STREAMOFF, (unsigned long)&type);
  close(fd);

  return 0;
}

