#include "periph_ctrl.h"
#include "esp32s3_board_cam_pinmap.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* Default pin definitions - override via board header */

#ifndef ESP32S3_CAM_PIN_D0
#  define ESP32S3_CAM_PIN_D0   11
#endif
#ifndef ESP32S3_CAM_PIN_D1
#  define ESP32S3_CAM_PIN_D1    9
#endif
#ifndef ESP32S3_CAM_PIN_D2
#  define ESP32S3_CAM_PIN_D2    8
#endif
#ifndef ESP32S3_CAM_PIN_D3
#  define ESP32S3_CAM_PIN_D3   10
#endif
#ifndef ESP32S3_CAM_PIN_D4
#  define ESP32S3_CAM_PIN_D4   12
#endif
#ifndef ESP32S3_CAM_PIN_D5
#  define ESP32S3_CAM_PIN_D5   18
#endif
#ifndef ESP32S3_CAM_PIN_D6
#  define ESP32S3_CAM_PIN_D6   17
#endif
#ifndef ESP32S3_CAM_PIN_D7
#  define ESP32S3_CAM_PIN_D7   16
#endif
#ifndef ESP32S3_CAM_PIN_PCLK
#  define ESP32S3_CAM_PIN_PCLK 13
#endif
#ifndef ESP32S3_CAM_PIN_VSYNC
#  define ESP32S3_CAM_PIN_VSYNC 6
#endif
#ifndef ESP32S3_CAM_PIN_HREF
#  define ESP32S3_CAM_PIN_HREF  7
#endif
#ifndef ESP32S3_CAM_PIN_XCLK
#  define ESP32S3_CAM_PIN_XCLK 15
#endif

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct esp32s3_cam_s
{
  struct imgdata_s          data;     /* Image data interface (must be first) */
  volatile bool             capturing;
  uint8_t                  *buf;
  uint32_t                  buf_size;
  uint16_t                  width;
  uint16_t                  height;
  imgdata_capture_t         callback;
  void                     *cb_arg;
  spinlock_t                lock;
};

/****************************************************************************
 * Private Function Prototypes
 ****************************************************************************/

static int esp32s3_cam_init(FAR struct imgdata_s *data);
static int esp32s3_cam_uninit(FAR struct imgdata_s *data);
static int esp32s3_cam_set_buf(FAR struct imgdata_s *data,
                                uint8_t nr_datafmts,
                                FAR imgdata_format_t *datafmts,
                                uint8_t *addr, uint32_t size);
static int esp32s3_cam_validate(FAR struct imgdata_s *data,
                                 uint8_t nr_datafmts,
                                 FAR imgdata_format_t *datafmts,
                                 FAR imgdata_interval_t *interval);
static int esp32s3_cam_start_capture(FAR struct imgdata_s *data,
                                      uint8_t nr_datafmts,
                                      FAR imgdata_format_t *datafmts,
                                      FAR imgdata_interval_t *interval,
                                      FAR imgdata_capture_t callback,
                                      FAR void *arg);
static int esp32s3_cam_stop_capture(FAR struct imgdata_s *data);

/****************************************************************************
 * Private Data
 ****************************************************************************/

static const struct imgdata_ops_s g_esp32s3_cam_ops =
{
  .init                   = esp32s3_cam_init,
  .uninit                 = esp32s3_cam_uninit,
  .set_buf                = esp32s3_cam_set_buf,
  .validate_frame_setting = esp32s3_cam_validate,
  .start_capture          = esp32s3_cam_start_capture,
  .stop_capture           = esp32s3_cam_stop_capture,
  .alloc                  = NULL,
  .free                   = NULL,
};

static struct esp32s3_cam_s g_esp32s3_cam;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: esp32s3_cam_init
 ****************************************************************************/

static int esp32s3_cam_init(FAR struct imgdata_s *data)
{
  caminfo("Initializing ESP32-S3 camera interface\n");

  /* Enable LCD_CAM peripheral clock */

  periph_ctrl_enable(PERIPH_LCD_CAM_MODULE);
  periph_ctrl_reset(PERIPH_LCD_CAM_MODULE);

  /* Configure data pins D0-D7 as input with pull-up */

  esp32s3_configgpio(ESP32S3_CAM_PIN_D0, INPUT_PULLUP);
  esp32s3_configgpio(ESP32S3_CAM_PIN_D1, INPUT_PULLUP);
  esp32s3_configgpio(ESP32S3_CAM_PIN_D2, INPUT_PULLUP);
  esp32s3_configgpio(ESP32S3_CAM_PIN_D3, INPUT_PULLUP);
  esp32s3_configgpio(ESP32S3_CAM_PIN_D4, INPUT_PULLUP);
  esp32s3_configgpio(ESP32S3_CAM_PIN_D5, INPUT_PULLUP);
  esp32s3_configgpio(ESP32S3_CAM_PIN_D6, INPUT_PULLUP);
  esp32s3_configgpio(ESP32S3_CAM_PIN_D7, INPUT_PULLUP);

  /* Connect data pins to LCD_CAM CAM data signals via GPIO matrix */

  esp32s3_gpio_matrix_in(ESP32S3_CAM_PIN_D0, CAM_DATA_IN0_IDX, 0);
  esp32s3_gpio_matrix_in(ESP32S3_CAM_PIN_D1, CAM_DATA_IN1_IDX, 0);
  esp32s3_gpio_matrix_in(ESP32S3_CAM_PIN_D2, CAM_DATA_IN2_IDX, 0);
  esp32s3_gpio_matrix_in(ESP32S3_CAM_PIN_D3, CAM_DATA_IN3_IDX, 0);
  esp32s3_gpio_matrix_in(ESP32S3_CAM_PIN_D4, CAM_DATA_IN4_IDX, 0);
  esp32s3_gpio_matrix_in(ESP32S3_CAM_PIN_D5, CAM_DATA_IN5_IDX, 0);
  esp32s3_gpio_matrix_in(ESP32S3_CAM_PIN_D6, CAM_DATA_IN6_IDX, 0);
  esp32s3_gpio_matrix_in(ESP32S3_CAM_PIN_D7, CAM_DATA_IN7_IDX, 0);

  /* Configure PCLK, VSYNC, HREF as input */

  esp32s3_configgpio(ESP32S3_CAM_PIN_PCLK, INPUT_PULLUP);
  esp32s3_configgpio(ESP32S3_CAM_PIN_VSYNC, INPUT_PULLUP);
  esp32s3_configgpio(ESP32S3_CAM_PIN_HREF, INPUT_PULLUP);

  /* Connect control signals to LCD_CAM */

  esp32s3_gpio_matrix_in(ESP32S3_CAM_PIN_PCLK, CAM_PCLK_IDX, 0);
  esp32s3_gpio_matrix_in(ESP32S3_CAM_PIN_VSYNC, CAM_V_SYNC_IDX, 0);
  esp32s3_gpio_matrix_in(ESP32S3_CAM_PIN_HREF, CAM_H_ENABLE_IDX, 0);

  /* Configure XCLK output (use LEDC or GPIO clock output) */

  esp32s3_configgpio(ESP32S3_CAM_PIN_XCLK, OUTPUT);

  caminfo("Camera interface initialized\n");
  return OK;
}

/****************************************************************************
 * Name: esp32s3_cam_uninit
 ****************************************************************************/

static int esp32s3_cam_uninit(FAR struct imgdata_s *data)
{
  caminfo("Uninitializing camera interface\n");

  periph_ctrl_disable(PERIPH_LCD_CAM_MODULE);
  return OK;
}

/****************************************************************************
 * Name: esp32s3_cam_set_buf
 ****************************************************************************/

static int esp32s3_cam_set_buf(FAR struct imgdata_s *data,
                                uint8_t nr_datafmts,
                                FAR imgdata_format_t *datafmts,
                                uint8_t *addr, uint32_t size)
{
  FAR struct esp32s3_cam_s *priv = (FAR struct esp32s3_cam_s *)data;

  if (nr_datafmts == 0 || datafmts == NULL)
    {
      return -EINVAL;
    }

  priv->buf      = addr;
  priv->buf_size = size;
  priv->width    = datafmts[0].width;
  priv->height   = datafmts[0].height;

  caminfo("Buffer set: %dx%d, size=%lu\n",
          priv->width, priv->height, (unsigned long)size);
  return OK;
}

/****************************************************************************
 * Name: esp32s3_cam_validate
 ****************************************************************************/

static int esp32s3_cam_validate(FAR struct imgdata_s *data,
                                 uint8_t nr_datafmts,
                                 FAR imgdata_format_t *datafmts,
                                 FAR imgdata_interval_t *interval)
{
  if (nr_datafmts == 0 || datafmts == NULL)
    {
      return -EINVAL;
    }

  caminfo("Validation OK: %dx%d\n",
          datafmts[0].width, datafmts[0].height);
  return OK;
}

/****************************************************************************
 * Name: esp32s3_cam_start_capture
 ****************************************************************************/

static int esp32s3_cam_start_capture(FAR struct imgdata_s *data,
                                      uint8_t nr_datafmts,
                                      FAR imgdata_format_t *datafmts,
                                      FAR imgdata_interval_t *interval,
                                      FAR imgdata_capture_t callback,
                                      FAR void *arg)
{
  FAR struct esp32s3_cam_s *priv = (FAR struct esp32s3_cam_s *)data;
  irqstate_t flags;

  if (priv->buf == NULL)
    {
      camerr("ERROR: No buffer set\n");
      return -ENOMEM;
    }

  caminfo("Starting capture: %dx%d\n", priv->width, priv->height);

  flags = spin_lock_irqsave(&priv->lock);
  priv->callback  = callback;
  priv->cb_arg    = arg;
  priv->capturing = true;
  spin_unlock_irqrestore(&priv->lock, flags);

  caminfo("Capture started\n");
  return OK;
}

/****************************************************************************
 * Name: esp32s3_cam_stop_capture
 ****************************************************************************/

static int esp32s3_cam_stop_capture(FAR struct imgdata_s *data)
{
  FAR struct esp32s3_cam_s *priv = (FAR struct esp32s3_cam_s *)data;
  irqstate_t flags;

  flags = spin_lock_irqsave(&priv->lock);
  priv->capturing = false;
  priv->callback  = NULL;
  priv->cb_arg    = NULL;
  spin_unlock_irqrestore(&priv->lock, flags);

  caminfo("Capture stopped\n");
  return OK;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: esp32s3_cam_initialize
 ****************************************************************************/

int esp32s3_cam_initialize(void)
{
  FAR struct esp32s3_cam_s *priv = &g_esp32s3_cam;

  caminfo("Registering ESP32-S3 camera data interface\n");

  memset(priv, 0, sizeof(struct esp32s3_cam_s));
  priv->data.ops = &g_esp32s3_cam_ops;

  /* Register image data interface */

  imgdata_register(&priv->data);

  caminfo("Camera data interface registered\n");
  return OK;
}

/****************************************************************************
 * Contest 2026 team 026 - OV2640 Camera Real-time Display
 *
 * Captures frames from OV2640 camera via V4L2 interface and displays
 * them on the ST7789 LCD in real-time.
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <sys/mman.h>

#include <nuttx/video/video.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define CAMERA_DEV_PATH   "/dev/video"
#define FB_DEV_PATH       "/dev/fb0"
#define FRAME_WIDTH       320
#define FRAME_HEIGHT      240
#define FRAME_SIZE        (FRAME_WIDTH * FRAME_HEIGHT * 2)  /* RGB565 */
#define LCD_WIDTH         240
#define LCD_HEIGHT        240
#define CROP_X            ((FRAME_WIDTH - LCD_WIDTH) / 2)   /* 40 */
#define BUF_COUNT         3

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: display_frame
 *
 * Description:
 *   Display a 320x240 RGB565 frame on the 240x240 LCD by center cropping.
 ****************************************************************************/

static int display_frame(int fb_fd, const uint8_t *frame,
                         struct fb_videoinfo_s *vinfo,
                         struct fb_planeinfo_s *pinfo)
{
  uint8_t *fbmem = (uint8_t *)pinfo->fbmem;
  int y;

  if (fbmem == NULL)
    {
      return -ENOMEM;
    }

  /* Center crop: take middle 240 columns from 320-wide frame */

  for (y = 0; y < LCD_HEIGHT; y++)
    {
      const uint16_t *src = (const uint16_t *)(frame +
                              (y * FRAME_WIDTH + CROP_X) * 2);
      uint16_t *dst = (uint16_t *)(fbmem + y * pinfo->stride);
      memcpy(dst, src, LCD_WIDTH * 2);
    }

  return OK;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, char *argv[])
{
  int cam_fd;
  int fb_fd;
  int ret;
  struct v4l2_format fmt;
  struct v4l2_requestbuffers req;
  struct v4l2_buffer buf;
  enum v4l2_buf_type type;
  struct fb_videoinfo_s vinfo;
  struct fb_planeinfo_s pinfo;
  struct timeval start_tv;
  struct timeval now_tv;
  int frame_count = 0;
  uint8_t *frame_data;

  printf("OV2640 Camera -> LCD Real-time Display\n");

  /* Open framebuffer device */

  fb_fd = open(FB_DEV_PATH, O_RDWR);
  if (fb_fd < 0)
    {
      printf("ERROR: Failed to open %s: %d\n", FB_DEV_PATH, errno);
      return -errno;
    }

  /* Get framebuffer info */

  ret = ioctl(fb_fd, FBIOGET_VIDEOINFO, (unsigned long)&vinfo);
  if (ret < 0)
    {
      printf("ERROR: FBIOGET_VIDEOINFO failed: %d\n", errno);
      close(fb_fd);
      return ret;
    }

  ret = ioctl(fb_fd, FBIOGET_PLANEINFO, (unsigned long)&pinfo);
  if (ret < 0)
    {
      printf("ERROR: FBIOGET_PLANEINFO failed: %d\n", errno);
      close(fb_fd);
      return ret;
    }

  printf("LCD: %dx%d, stride=%d\n", vinfo.xres, vinfo.yres, pinfo.stride);

  /* Open camera device */

  cam_fd = open(CAMERA_DEV_PATH, O_RDONLY);
  if (cam_fd < 0)
    {
      printf("ERROR: Failed to open %s: %d\n", CAMERA_DEV_PATH, errno);
      close(fb_fd);
      return -errno;
    }

  /* Set camera format: QVGA RGB565 */

  memset(&fmt, 0, sizeof(fmt));
  fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  fmt.fmt.pix.width = FRAME_WIDTH;
  fmt.fmt.pix.height = FRAME_HEIGHT;
  fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_RGB565;

  ret = ioctl(cam_fd, VIDIOC_S_FMT, (unsigned long)&fmt);
  if (ret < 0)
    {
      printf("ERROR: VIDIOC_S_FMT failed: %d\n", errno);
      goto err_close;
    }

  /* Request buffers */

  memset(&req, 0, sizeof(req));
  req.count = BUF_COUNT;
  req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  req.memory = V4L2_MEMORY_MMAP;

  ret = ioctl(cam_fd, VIDIOC_REQBUFS, (unsigned long)&req);
  if (ret < 0)
    {
      printf("ERROR: VIDIOC_REQBUFS failed: %d\n", errno);
      goto err_close;
    }

  /* Queue all buffers */

  for (int i = 0; i < BUF_COUNT; i++)
    {
      memset(&buf, 0, sizeof(buf));
      buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
      buf.memory = V4L2_MEMORY_MMAP;
      buf.index = i;

      ret = ioctl(cam_fd, VIDIOC_QBUF, (unsigned long)&buf);
      if (ret < 0)
        {
          printf("ERROR: VIDIOC_QBUF[%d] failed: %d\n", i, errno);
          goto err_close;
        }
    }

  /* Start streaming */

  type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  ret = ioctl(cam_fd, VIDIOC_STREAMON, (unsigned long)&type);
  if (ret < 0)
    {
      printf("ERROR: VIDIOC_STREAMON failed: %d\n", errno);
      goto err_close;
    }

  printf("Camera streaming started. Press Ctrl+C to stop.\n");
  gettimeofday(&start_tv, NULL);

  /* Main capture loop */

  while (1)
    {
      /* Dequeue a frame */

      memset(&buf, 0, sizeof(buf));
      buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
      buf.memory = V4L2_MEMORY_MMAP;

      ret = ioctl(cam_fd, VIDIOC_DQBUF, (unsigned long)&buf);
      if (ret < 0)
        {
          printf("ERROR: VIDIOC_DQBUF failed: %d\n", errno);
          break;
        }

      /* Map frame data */

      frame_data = (uint8_t *)mmap(NULL, buf.length, PROT_READ,
                                    MAP_SHARED, cam_fd, buf.m.offset);
      if (frame_data == MAP_FAILED)
        {
          printf("ERROR: mmap failed: %d\n", errno);
          break;
        }

      /* Display frame on LCD */

      display_frame(fb_fd, frame_data, &vinfo, &pinfo);

      /* Unmap */

      munmap(frame_data, buf.length);

      /* Requeue buffer */

      ret = ioctl(cam_fd, VIDIOC_QBUF, (unsigned long)&buf);
      if (ret < 0)
        {
          printf("ERROR: VIDIOC_QBUF failed: %d\n", errno);
          break;
        }

      /* Print FPS every second */

      frame_count++;
      gettimeofday(&now_tv, NULL);
      long elapsed_ms = (now_tv.tv_sec - start_tv.tv_sec) * 1000 +
                        (now_tv.tv_usec - start_tv.tv_usec) / 1000;

      if (elapsed_ms >= 1000)
        {
          printf("FPS: %ld\n", frame_count * 1000 / elapsed_ms);
          frame_count = 0;
          start_tv = now_tv;
        }
    }

  /* Cleanup */

  ioctl(cam_fd, VIDIOC_STREAMOFF, (unsigned long)&type);

err_close:
  close(cam_fd);
  close(fb_fd);
  return 0;
}

