/* Default pin definitions - override via board header */

#ifndef ESP32S3_DAMI_CAM_PIN_D0
#  define ESP32S3_DAMI_CAM_PIN_D0   11
#endif
#ifndef ESP32S3_DAMI_CAM_PIN_D1
#  define ESP32S3_DAMI_CAM_PIN_D1    9
#endif
#ifndef ESP32S3_DAMI_CAM_PIN_D2
