#ifndef ESP32S3_DAMI_CAM_PIN_HREF
#  define ESP32S3_DAMI_CAM_PIN_HREF  7
#endif
#ifndef ESP32S3_DAMI_CAM_PIN_XCLK
#  define ESP32S3_DAMI_CAM_PIN_XCLK 15
#endif

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct esp32s3_cam_s
{
  struct imgdata_s          data;
  volatile bool             capturing;
  uint8_t                  *buf;
  uint32_t                  buf_size;
  uint16_t                  width;
