  .stop_capture           = esp32s3_cam_stop_capture,
  .alloc                  = NULL,
  .free                   = NULL,
};

static struct esp32s3_cam_s g_esp32s3_cam;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static int esp32s3_cam_init(FAR struct imgdata_s *data)
{
  syslog(LOG_INFO, "cam: initializing ESP32-S3 camera interface\n");

  periph_module_enable(PERIPH_LCD_CAM_MODULE);
  periph_module_reset(PERIPH_LCD_CAM_MODULE);

  /* Configure data pins D0-D7 as input */

  esp32s3_configgpio(ESP32S3_DAMI_CAM_PIN_D0, INPUT_PULLUP);
  esp32s3_configgpio(ESP32S3_DAMI_CAM_PIN_D1, INPUT_PULLUP);
  esp32s3_configgpio(ESP32S3_DAMI_CAM_PIN_D2, INPUT_PULLUP);
  esp32s3_configgpio(ESP32S3_DAMI_CAM_PIN_D3, INPUT_PULLUP);
  esp32s3_configgpio(ESP32S3_DAMI_CAM_PIN_D4, INPUT_PULLUP);
  esp32s3_configgpio(ESP32S3_DAMI_CAM_PIN_D5, INPUT_PULLUP);
  esp32s3_configgpio(ESP32S3_DAMI_CAM_PIN_D6, INPUT_PULLUP);
  esp32s3_configgpio(ESP32S3_DAMI_CAM_PIN_D7, INPUT_PULLUP);

  /* Connect data pins to LCD_CAM CAM data signals */

  esp32s3_gpio_matrix_in(ESP32S3_DAMI_CAM_PIN_D0, CAM_DATA_IN0_IDX, 0);
  esp32s3_gpio_matrix_in(ESP32S3_DAMI_CAM_PIN_D1, CAM_DATA_IN1_IDX, 0);
  esp32s3_gpio_matrix_in(ESP32S3_DAMI_CAM_PIN_D2, CAM_DATA_IN2_IDX, 0);
  esp32s3_gpio_matrix_in(ESP32S3_DAMI_CAM_PIN_D3, CAM_DATA_IN3_IDX, 0);
  esp32s3_gpio_matrix_in(ESP32S3_DAMI_CAM_PIN_D4, CAM_DATA_IN4_IDX, 0);
  esp32s3_gpio_matrix_in(ESP32S3_DAMI_CAM_PIN_D5, CAM_DATA_IN5_IDX, 0);
  esp32s3_gpio_matrix_in(ESP32S3_DAMI_CAM_PIN_D6, CAM_DATA_IN6_IDX, 0);
  esp32s3_gpio_matrix_in(ESP32S3_DAMI_CAM_PIN_D7, CAM_DATA_IN7_IDX, 0);

  /* Configure PCLK, VSYNC, HREF as input */

  esp32s3_configgpio(ESP32S3_DAMI_CAM_PIN_PCLK, INPUT_PULLUP);
  esp32s3_configgpio(ESP32S3_DAMI_CAM_PIN_VSYNC, INPUT_PULLUP);
  esp32s3_configgpio(ESP32S3_DAMI_CAM_PIN_HREF, INPUT_PULLUP);

  /* Connect control signals to LCD_CAM */

  esp32s3_gpio_matrix_in(ESP32S3_DAMI_CAM_PIN_PCLK, CAM_PCLK_IDX, 0);
  esp32s3_gpio_matrix_in(ESP32S3_DAMI_CAM_PIN_VSYNC, CAM_V_SYNC_IDX, 0);
  esp32s3_gpio_matrix_in(ESP32S3_DAMI_CAM_PIN_HREF, CAM_H_ENABLE_IDX, 0);

  /* Configure XCLK output pin */

  esp32s3_configgpio(ESP32S3_DAMI_CAM_PIN_XCLK, OUTPUT);

  syslog(LOG_INFO, "cam: camera interface initialized\n");
  return OK;
}

static int esp32s3_cam_uninit(FAR struct imgdata_s *data)
{
  syslog(LOG_INFO, "cam: uninitializing camera interface\n");
  periph_module_disable(PERIPH_LCD_CAM_MODULE);
  return OK;
}

static int esp32s3_cam_set_buf(FAR struct imgdata_s *data,
                                uint8_t nr_datafmts,
                                FAR imgdata_format_t *datafmts,
                                uint8_t *addr, uint32_t size)
{
  FAR struct esp32s3_cam_s *priv = (FAR struct esp32s3_cam_s *)data;

  if (nr_datafmts == 0 || datafmts == NULL)
    {
      return -EINVAL;
    }

  priv->buf      = addr;
  priv->buf_size = size;
  priv->width    = datafmts[0].width;
  priv->height   = datafmts[0].height;

  syslog(LOG_INFO, "cam: buffer set %dx%d size=%lu\n",
         priv->width, priv->height, (unsigned long)size);
  return OK;
}

static int esp32s3_cam_validate(FAR struct imgdata_s *data,
                                 uint8_t nr_datafmts,
                                 FAR imgdata_format_t *datafmts,
                                 FAR imgdata_interval_t *interval)
{
  if (nr_datafmts == 0 || datafmts == NULL)
    {
      return -EINVAL;
    }

  syslog(LOG_INFO, "cam: validate %dx%d\n",
         datafmts[0].width, datafmts[0].height);
  return OK;
}

static int esp32s3_cam_start_capture(FAR struct imgdata_s *data,
                                      uint8_t nr_datafmts,
                                      FAR imgdata_format_t *datafmts,
                                      FAR imgdata_interval_t *interval,
                                      FAR imgdata_capture_t callback,
                                      FAR void *arg)
{
  FAR struct esp32s3_cam_s *priv = (FAR struct esp32s3_cam_s *)data;
  irqstate_t flags;

  if (priv->buf == NULL)
    {
      syslog(LOG_ERR, "cam: no buffer set\n");
      return -ENOMEM;
    }

  syslog(LOG_INFO, "cam: start capture %dx%d\n",
         priv->width, priv->height);

  flags = spin_lock_irqsave(&priv->lock);
  priv->callback  = callback;
  priv->cb_arg    = arg;
  priv->capturing = true;
  spin_unlock_irqrestore(&priv->lock, flags);

  return OK;
}

static int esp32s3_cam_stop_capture(FAR struct imgdata_s *data)
{
  FAR struct esp32s3_cam_s *priv = (FAR struct esp32s3_cam_s *)data;
  irqstate_t flags;

  flags = spin_lock_irqsave(&priv->lock);
  priv->capturing = false;
  priv->callback  = NULL;
  priv->cb_arg    = NULL;
  spin_unlock_irqrestore(&priv->lock, flags);

  syslog(LOG_INFO, "cam: stop capture\n");
  return OK;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int esp32s3_cam_initialize(void)
{
  FAR struct esp32s3_cam_s *priv = &g_esp32s3_cam;

  syslog(LOG_INFO, "cam: registering camera data interface\n");

  memset(priv, 0, sizeof(struct esp32s3_cam_s));
  priv->data.ops = &g_esp32s3_cam_ops;

  imgdata_register(&priv->data);

  syslog(LOG_INFO, "cam: camera data interface registered\n");
  return OK;
}

