#include <nuttx/config.h>

#include <syslog.h>
#include <errno.h>

#include <nuttx/i2c/i2c_master.h>
#include <nuttx/video/ov2640.h>
#include <nuttx/video/v4l2_cap.h>

#include "esp32s3_cam.h"
#include "esp32s3_i2c.h"

#include "esp32dami.h"

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int board_camera_initialize(void)
{
  FAR struct i2c_master_s *i2c;
  int ret;

  syslog(LOG_INFO, "board_camera: initializing OV2640\n");

  /* Initialize I2C bus for SCCB */

  i2c = esp32s3_i2cbus_initialize(0);
  if (i2c == NULL)
    {
      syslog(LOG_ERR, "board_camera: I2C init failed\n");
      return -ENODEV;
    }

  /* Initialize OV2640 sensor */

  ret = ov2640_initialize(i2c);
  if (ret < 0)
    {
      syslog(LOG_ERR, "board_camera: ov2640 init failed: %d\n", ret);
      return ret;
    }

  /* Initialize camera data interface */

  ret = esp32s3_cam_initialize();
  if (ret < 0)
    {
      syslog(LOG_ERR, "board_camera: cam init failed: %d\n", ret);
      return ret;
    }

  /* Register V4L2 capture device */

  ret = capture_register("/dev/video", NULL, NULL, 0);
  if (ret < 0)
    {
      syslog(LOG_ERR, "board_camera: capture_register failed: %d\n", ret);
      return ret;
    }

  syslog(LOG_INFO, "board_camera: done\n");
  return OK;
}
